<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Application\Policy\Allow\Update;

use Throwable;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\Update\SnippetAssetUpdateAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedUpdateAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(SnippetAssetUpdateAllowDecision $proposal): SnippetAssetUpdateAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedUpdateAllow Snippet asset");
        $span = $this->startSpan("Check IsAuthenticatedUpdateAllow Snippet asset");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (! !$userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedUpdate');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
